-- StarterGui.Eternity.Toggle
local function C_4()
local script = G2L["4"];
	--// Place this LocalScript inside StarterGui -> ScreenGui
	--// Make sure there's a Frame named "MenuFrame" inside the same ScreenGui

	local UserInputService = game:GetService("UserInputService")
	local TweenService = game:GetService("TweenService")

	local gui = script.Parent
	local frame = gui:WaitForChild("MenuFrame")

	-- Configuration
	local slideDistance = UDim2.new(0, 0, 0.1, 0)  -- how much it slides from its position
	local tweenTime = 0.3  -- animation duration (seconds)

	-- Initial state (hidden)
	frame.Visible = false
	frame.BackgroundTransparency = 1
	local originalPosition = frame.Position

	-- State tracker
	local isOpen = false

	-- Tween functions
	local function openFrame()
		frame.Visible = true
		frame.Position = originalPosition + slideDistance
		frame.BackgroundTransparency = 1

		local tweenInfo = TweenInfo.new(tweenTime, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		TweenService:Create(frame, tweenInfo, {
			Position = originalPosition,
			BackgroundTransparency = 0
		}):Play()
	end

	local function closeFrame()
		local tweenInfo = TweenInfo.new(tweenTime, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		local tween = TweenService:Create(frame, tweenInfo, {
			Position = originalPosition + slideDistance,
			BackgroundTransparency = 1
		})
		tween:Play()
		tween.Completed:Wait()
		frame.Visible = false
	end

	-- Toggle on key press (;)
	UserInputService.InputBegan:Connect(function(input, gameProcessed)
		if gameProcessed then return end

		if input.KeyCode == Enum.KeyCode.Semicolon then
			isOpen = not isOpen
			if isOpen then
				openFrame()
			else
				closeFrame()
			end
		end
	end)

end;
