	local colors = {
		Color3.fromRGB(68, 93, 255),
		Color3.fromRGB(125, 180, 200),
		Color3.fromRGB(82, 255, 153)
	}

	local index = 1

	-- Function to tween the gradient color smoothly
	local function tweenGradient()
		local nextIndex = index % #colors + 1
		local tweenInfo = TweenInfo.new(2, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut) -- 2 seconds
		local tween = TweenService:Create(gradient, tweenInfo, {
			Color = ColorSequence.new{
				ColorSequenceKeypoint.new(0, colors[index]),
				ColorSequenceKeypoint.new(1, colors[nextIndex])
			}
		})
		tween:Play()
		tween.Completed:Wait()
		index = nextIndex
		tweenGradient()
	end

	tweenGradient()

end;
