	--// Player Time Display Script (No Seconds)
	--// Place this LocalScript inside a TextLabel

	local textLabel = script.Parent

	-- Optional styling
	textLabel.TextScaled = true
	textLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
	textLabel.BackgroundTransparency = 1
	textLabel.Font = Enum.Font.GothamBold

	-- Function to format and update the time
	local function updateTime()
		while true do
			local currentTime = os.date("*t") -- Gets local time from player’s device
			local hour = currentTime.hour
			local minute = currentTime.min

			-- Convert to 12-hour format
			local suffix = "AM"
			if hour >= 12 then
				suffix = "PM"
				if hour > 12 then
					hour -= 12
				end
			elseif hour == 0 then
				hour = 12
			end

			-- Format time with leading zero on minutes
			local formattedTime = string.format("%d:%02d %s", hour, minute, suffix)
			textLabel.Text = formattedTime

			task.wait(2) -- update every 2 seconds
		end
	end

	-- Start updating
	task.spawn(updateTime)

end;
