local function C_125()
local script = G2L["125"];
	--// LocalScript
	--// Put this inside the Frame you want to animate

	local frame = script.Parent
	local TweenService = game:GetService("TweenService")
	local UserInputService = game:GetService("UserInputService")

	-- Positions
	local startPos = UDim2.new(2, 0, 0.93, 0) -- Off-screen (right)
	local endPos = UDim2.new(0.916, 0, 0.93, 0) -- On-screen (final)
	local outPos = UDim2.new(2, 0, 0.93, 0) -- Slide out to the right again

	-- Animation settings
	local tweenInfo = TweenInfo.new(
		0.8, -- duration
		Enum.EasingStyle.Quad,
		Enum.EasingDirection.Out
	)

	-- Set initial position
	frame.Position = startPos
	frame.AnchorPoint = Vector2.new(0.5, 0.5)

	-- Slide in once when GUI loads
	task.wait(1)
	local slideIn = TweenService:Create(frame, tweenInfo, { Position = endPos })
	slideIn:Play()

	-- Wait for key press to slide out
	UserInputService.InputBegan:Connect(function(input, gameProcessed)
		if gameProcessed then return end
		if input.KeyCode == Enum.KeyCode.Semicolon then
			local slideOut = TweenService:Create(frame, tweenInfo, { Position = outPos })
			slideOut:Play()
		end
	end)

end;
